import { applyGravity } from '../physics';

const GRAVITY = 1800; // px/s² (positive = downward)
const JUMP_IMPULSE = -600; // px/s (negative = upward)
const DINO_WIDTH = 40;
const DINO_HEIGHT = 50;

/** Create a grounded dino at the origin. */
export function createDino(): DinoEntity {
  return {
    id: 'dino',
    x: 50,
    y: 0,
    width: DINO_WIDTH,
    height: DINO_HEIGHT,
    isJumping: false,
    velocityY: 0,
  };
}

/** Pure tick update: apply gravity, move, clamp to ground. */
export function updateDino(dino: DinoEntity, dt: number): DinoEntity {
  const velocityY = applyGravity(dino.velocityY, GRAVITY, dt);
  let y = dino.y + velocityY * dt;

  // Clamp to ground level
  if (y >= 0) {
    return { ...dino, y: 0, velocityY: 0, isJumping: false };
  }

  return { ...dino, y, velocityY, isJumping: true };
}

/** Apply jump impulse if grounded. */
export function jumpDino(dino: DinoEntity): DinoEntity {
  if (dino.isJumping) return dino;
  return { ...dino, velocityY: JUMP_IMPULSE, isJumping: true };
}
