/** Minimum gap (px) between the rightmost obstacle and the canvas right edge before a new spawn is considered. */
const MIN_SPAWN_GAP = 300;

/** Probability of spawning a new obstacle each eligible frame. */
const SPAWN_PROBABILITY = 0.02;

/** Obstacle fixed width (px). */
const OBSTACLE_WIDTH = 20;

let nextId = 0;

/**
 * Spawn a single cactus obstacle at the right edge of the canvas
 * with a randomised height between 30–60 px.
 */
export function spawnObstacle(canvasWidth: number): ObstacleEntity {
  const height = 30 + Math.random() * 30; // 30–60 px
  return {
    id: `obstacle-${nextId++}`,
    x: canvasWidth,
    y: 0, // ground-level (renderer will align bottom)
    width: OBSTACLE_WIDTH,
    height,
    isJumping: false,
    velocityY: 0,
  } as unknown as ObstacleEntity;
}

/**
 * Pure update: move obstacles left, cull off-screen, probabilistically spawn new ones.
 */
export function updateObstacles(
  obstacles: ObstacleEntity[],
  speed: number,
  dt: number,
  canvasWidth: number,
): ObstacleEntity[] {
  // Move existing obstacles left
  const moved = obstacles.map((o) => ({
    ...o,
    x: o.x - speed * dt,
  }));

  // Remove obstacles that have scrolled fully off the left edge
  const visible = moved.filter((o) => o.x + o.width > 0);

  // Determine if we should spawn a new obstacle
  const rightmost = visible.length > 0 ? Math.max(...visible.map((o) => o.x)) : -Infinity;
  const gapFromEdge = canvasWidth - rightmost;

  if (gapFromEdge >= MIN_SPAWN_GAP && Math.random() < SPAWN_PROBABILITY) {
    return [...visible, spawnObstacle(canvasWidth)];
  }

  return visible;
}
