const DINO_COLOR = '#535353';

/**
 * Draw the dino as a filled rectangle.
 * Game coordinates: y=0 is ground, negative y is upward.
 * Canvas coordinates: groundY is the ground line, y increases downward.
 */
export function renderDino(
  ctx: CanvasRenderingContext2D,
  dino: DinoEntity,
  groundY: number,
) {
  ctx.fillStyle = DINO_COLOR;
  // Convert game y (0 = ground, negative = up) to canvas y
  const canvasY = groundY - dino.height - (-dino.y);
  ctx.fillRect(dino.x, canvasY, dino.width, dino.height);
}
