const OBSTACLE_COLOR = '#2e7d32';

/**
 * Draw each obstacle (cactus) as a filled rectangle sitting on the ground.
 */
export function renderObstacles(
  ctx: CanvasRenderingContext2D,
  obstacles: ObstacleEntity[],
  groundY: number,
) {
  ctx.fillStyle = OBSTACLE_COLOR;
  for (const obs of obstacles) {
    const canvasY = groundY - obs.height;
    ctx.fillRect(obs.x, canvasY, obs.width, obs.height);
  }
}
