const DASH_LENGTH = 20;
const GAP_LENGTH = 10;
const LINE_WIDTH = 2;

/**
 * Draw a scrolling ground line at the given y position.
 * `offset` is the cumulative scroll distance used to animate the dashes.
 */
export function renderGround(
  ctx: CanvasRenderingContext2D,
  groundY: number,
  width: number,
  offset: number,
) {
  ctx.strokeStyle = GROUND_COLOR;
  ctx.lineWidth = LINE_WIDTH;

  // Solid baseline
  ctx.beginPath();
  ctx.moveTo(0, groundY);
  ctx.lineTo(width, groundY);
  ctx.stroke();

  // Scrolling dashed line beneath the baseline for ground texture
  const dashY = groundY + 8;
  const period = DASH_LENGTH + GAP_LENGTH;
  // Normalize offset into one period to avoid large float drift
  const shift = -(offset % period);

  ctx.beginPath();
  let x = shift - period; // start before the left edge to cover gaps
  while (x < width) {
    const startX = Math.max(x, 0);
    const endX = Math.min(x + DASH_LENGTH, width);
    if (endX > 0) {
      ctx.moveTo(startX, dashY);
      ctx.lineTo(endX, dashY);
    }
    x += period;
  }
  ctx.stroke();
}
