import { renderDino } from './canvas/DinoRender';
import { renderObstacles } from './canvas/ObstacleRender';
import { renderGround } from './canvas/GroundRender';

/** Vertical margin from the bottom of the canvas to the ground line. */
const GROUND_MARGIN = 40;

/**
 * Top-level render function: clears the canvas and draws ground, obstacles, and dino.
 *
 * `groundOffset` is the cumulative horizontal scroll distance used to
 * animate the scrolling ground dashes.
 */
export function renderGame(
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  state: DinoGameState,
  groundOffset: number,
) {
  // Clear the entire canvas
  ctx.clearRect(0, 0, width, height);

  const groundY = height - GROUND_MARGIN;

  // Draw layers back-to-front
  renderGround(ctx, groundY, width, groundOffset);
  renderObstacles(ctx, state.obstacles, groundY);
  renderDino(ctx, state.dino, groundY);
}
